        margin: 0;
        padding: 0.35rem 0.75rem;
        border-radius: 999px;
        background: rgba(155, 77, 202, 0.12);
        color: var(--accent-dark);
        font-size: 0.875rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

