          border: 1px solid CanvasText;
        }

        .question:focus-visible {
          outline: 3px solid Highlight;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <main id="main-content" class="page">
      <section class="hero" aria-labelledby="page-title">
        <p class="eyebrow">Cat care basics</p>
        <h1 id="page-title">Frequently asked cat questions</h1>
        <p class="intro">
          Quick answers for curious cat people, from purring and sleep habits to
          scratching, whiskers, and safe indoor enrichment.
        </p>
      </section>

      <div class="faq-list">
        <div class="example">
          <h2>
            <button class="question" type="button" aria-expanded="false" aria-controls="answer-purr">
              Why do cats purr?
            </button>
          </h2>
          <div class="details" id="answer-purr">
            <p>
              Cats often purr when they are relaxed, but they may also purr to
              self-soothe when stressed, injured, or asking for attention.
            </p>
          </div>
        </div>

        <div class="example">
          <h2>
            <button class="question" type="button" aria-expanded="false" aria-controls="answer-sleep">
              How much do cats sleep each day?
            </button>
          </h2>
          <div class="details" id="answer-sleep">
            <p>
              Most adult cats sleep 12 to 16 hours a day. Kittens, seniors, and
              very active cats may sleep even more as part of a normal routine.
            </p>
          </div>
        </div>

        <div class="example">
          <h2>
            <button class="question" type="button" aria-expanded="false" aria-controls="answer-scratch">
              Why does my cat scratch furniture?
            </button>
          </h2>
          <div class="details" id="answer-scratch">
            <p>
              Scratching stretches muscles, removes old claw layers, and marks
              territory. Provide sturdy scratching posts near favorite furniture
              and reward your cat for using them.
            </p>
          </div>
        </div>

        <div class="example">
          <h2>
            <button class="question" type="button" aria-expanded="false" aria-controls="answer-whiskers">
              What are cat whiskers for?
            </button>
          </h2>
          <div class="details" id="answer-whiskers">
            <p>
              Whiskers are sensitive touch tools that help cats judge spaces,
              detect nearby movement, and navigate in low light.
            </p>
          </div>
        </div>

        <div class="example">
          <h2>
            <button class="question" type="button" aria-expanded="false" aria-controls="answer-indoor">
              How can I keep an indoor cat entertained?
            </button>
          </h2>
          <div class="details" id="answer-indoor">
            <p>
              Rotate toys, offer climbing spots, schedule short play sessions,
              place perches near windows, and use puzzle feeders to make daily
              routines more engaging.
            </p>
          </div>
        </div>
      </div>
    </main>

    <script>
      document.querySelectorAll(".question").forEach((button) => {
        const panelId = button.getAttribute("aria-controls");
        const panel = document.getElementById(panelId);

        button.setAttribute("aria-expanded", "false");
        panel.hidden = true;

        button.addEventListener("click", () => {
          const isOpen = button.getAttribute("aria-expanded") === "true";
          button.setAttribute("aria-expanded", String(!isOpen));
          panel.hidden = isOpen;
        });

        button.addEventListener("keydown", (event) => {
          if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
            button.setAttribute("aria-expanded", "false");
            panel.hidden = true;
          }
        });
      });
    </script>
  </body>
</html>
